        {
          h: 'Степень окисления и валентность',
          html: String.raw`<p><b>Степень окисления</b> (СО) — условный заряд атома, если считать все связи ионными. <b>Валентность</b> — число связей, которые образует атом.</p>
<div class="rule"><b>Правила расстановки СО.</b><br>1) У простых веществ СО = 0.<br>2) Сумма СО в молекуле = 0, в ионе = заряду иона.<br>3) Постоянные: щелочные металлы +1, Mg, Ca, Ba, Zn +2, Al +3, F −1.<br>4) Водород обычно +1, но в гидридах металлов (NaH, CaH<sub>2</sub>) −1.<br>5) Кислород обычно −2, но в пероксидах (H<sub>2</sub>O<sub>2</sub>, Na<sub>2</sub>O<sub>2</sub>) −1, в OF<sub>2</sub> +2.</div>
<div class="example"><p><b>Пример.</b> СО марганца в KMnO<sub>4</sub>: (+1) + x + 4·(−2) = 0 → x = +7.</p>
<p>СО азота в (NH<sub>4</sub>)<sub>2</sub>SO<sub>4</sub>: в ионе NH<sub>4</sub><sup>+</sup> x + 4·(+1) = +1 → x = −3.</p></div>
<div class="trap">Валентность и СО не всегда совпадают. В HNO<sub>3</sub> СО азота +5, а валентность IV (у азота нет d-орбиталей, больше четырёх связей он не образует). В H<sub>2</sub>O<sub>2</sub> СО кислорода −1, а валентность II. В молекуле N<sub>2</sub> СО = 0, а валентность III.</div>
<div class="quick" data-a="+6|6">Степень окисления хрома в K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub>?</div>`
        }
