          html: String.raw`<p>Качественная реакция — это реакция с ярким видимым признаком, по которому узнают ион. На них построены задание 17 ОГЭ, задание 24 ЕГЭ и реальный эксперимент на ОГЭ.</p>
<table class="tbl">
<tr><th>Ион</th><th>Реактив</th><th>Признак</th></tr>
<tr><td>Cl<sup>−</sup></td><td>Ag<sup>+</sup> (AgNO<sub>3</sub>)</td><td>белый творожистый осадок AgCl</td></tr>
<tr><td>Br<sup>−</sup> / I<sup>−</sup></td><td>Ag<sup>+</sup></td><td>светло-жёлтый AgBr / жёлтый AgI</td></tr>
<tr><td>SO<sub>4</sub><sup>2−</sup></td><td>Ba<sup>2+</sup></td><td>белый осадок BaSO<sub>4</sub>, не растворяется в кислотах</td></tr>
<tr><td>CO<sub>3</sub><sup>2−</sup></td><td>H<sup>+</sup> (кислота)</td><td>«вскипание» — газ CO<sub>2</sub>, мутнеет известковая вода</td></tr>
<tr><td>PO<sub>4</sub><sup>3−</sup></td><td>Ag<sup>+</sup></td><td>жёлтый осадок Ag<sub>3</sub>PO<sub>4</sub></td></tr>
<tr><td>NH<sub>4</sub><sup>+</sup></td><td>OH<sup>−</sup>, нагревание</td><td>запах аммиака, влажная лакмусовая бумажка синеет</td></tr>
<tr><td>Fe<sup>3+</sup></td><td>OH<sup>−</sup>; KSCN</td><td>бурый осадок Fe(OH)<sub>3</sub>; кроваво-красный раствор</td></tr>
<tr><td>Fe<sup>2+</sup></td><td>OH<sup>−</sup>; K<sub>3</sub>[Fe(CN)<sub>6</sub>]</td><td>серо-зелёный осадок, буреющий на воздухе; синий осадок (турнбуллева синь)</td></tr>
<tr><td>Cu<sup>2+</sup></td><td>OH<sup>−</sup></td><td>голубой осадок Cu(OH)<sub>2</sub></td></tr>
</table>`
