          html: String.raw`<p>Соли слабых кислот или слабых оснований реагируют с водой — это <b>гидролиз</b>. Из-за него раствор соли может быть кислым или щелочным.</p>
<table class="tbl">
<tr><th>Соль образована</th><th>Гидролиз</th><th>Среда, pH</th><th>Примеры</th></tr>
<tr><td>сильным основанием и сильной кислотой</td><td>нет</td><td>нейтральная, pH = 7</td><td>NaCl, KNO<sub>3</sub>, K<sub>2</sub>SO<sub>4</sub></td></tr>
<tr><td>сильным основанием и слабой кислотой</td><td>по аниону</td><td>щелочная, pH &gt; 7</td><td>Na<sub>2</sub>CO<sub>3</sub>, K<sub>2</sub>S, CH<sub>3</sub>COONa, Na<sub>2</sub>SiO<sub>3</sub></td></tr>
<tr><td>слабым основанием и сильной кислотой</td><td>по катиону</td><td>кислая, pH &lt; 7</td><td>AlCl<sub>3</sub>, ZnSO<sub>4</sub>, NH<sub>4</sub>NO<sub>3</sub>, CuCl<sub>2</sub></td></tr>
<tr><td>слабым основанием и слабой кислотой</td><td>и по катиону, и по аниону</td><td>близка к нейтральной</td><td>CH<sub>3</sub>COONH<sub>4</sub></td></tr>
</table>
<div class="example"><p><b>Пример.</b> Почему раствор соды щелочной? CO<sub>3</sub><sup>2−</sup> + H<sub>2</sub>O ⇄ HCO<sub>3</sub><sup>−</sup> + OH<sup>−</sup> — накапливаются ионы OH<sup>−</sup>, фенолфталеин становится малиновым.</p></div>
<div class="tip"><b>Правило «кто сильнее, тот и победил»:</b> среда определяется сильным участником. Сильная кислота → кислая, сильное основание → щелочная. Некоторые соли (Al<sub>2</sub>S<sub>3</sub>, Cr<sub>2</sub>S<sub>3</sub>) гидролизуются необратимо и в водном растворе не существуют.</div>`
