        {
          h: 'Классификация реакций (ЕГЭ 17)',
          html: String.raw`<table class="tbl">
<tr><th>Признак</th><th>Типы</th><th>Пример</th></tr>
<tr><td>Число и состав веществ</td><td>соединения, разложения, замещения, обмена</td><td>CaO + CO<sub>2</sub> → CaCO<sub>3</sub> (соединение)<br>Fe + CuSO<sub>4</sub> → FeSO<sub>4</sub> + Cu (замещение)</td></tr>
<tr><td>Тепловой эффект</td><td>экзотермические (+Q), эндотермические (−Q)</td><td>горение — экзо; разложение CaCO<sub>3</sub> — эндо</td></tr>
<tr><td>Изменение СО</td><td>окислительно-восстановительные и без изменения СО</td><td>2H<sub>2</sub> + O<sub>2</sub> → 2H<sub>2</sub>O — ОВР</td></tr>
<tr><td>Обратимость</td><td>обратимые (⇄), необратимые</td><td>N<sub>2</sub> + 3H<sub>2</sub> ⇄ 2NH<sub>3</sub></td></tr>
<tr><td>Фазовый состав</td><td>гомогенные (одна фаза), гетерогенные (граница фаз)</td><td>2NO + O<sub>2</sub> → 2NO<sub>2</sub> — гомогенная; C + O<sub>2</sub> → CO<sub>2</sub> — гетерогенная</td></tr>
<tr><td>Катализатор</td><td>каталитические, некаталитические</td><td>2SO<sub>2</sub> + O<sub>2</sub> ⇄ 2SO<sub>3</sub> (катализатор V<sub>2</sub>O<sub>5</sub>)</td></tr>
</table>
<div class="trap"><b>Ловушка:</b> реакция соединения не обязательно ОВР (CaO + CO<sub>2</sub>), а реакция замещения — всегда ОВР. Реакции обмена никогда не бывают окислительно-восстановительными. Одна и та же реакция описывается сразу несколькими признаками — в ЕГЭ обычно просят выбрать два верных.</div>`
        },
        {
          h: 'Скорость реакции и её факторы',
          html: String.raw`<p>Скорость гомогенной реакции — изменение концентрации вещества за единицу времени: $v = \dfrac{\Delta c}{\Delta t}$, моль/(л·с).</p>
<table class="tbl">
<tr><th>Фактор</th><th>Как влияет</th></tr>
<tr><td>Природа веществ</td><td>K реагирует с водой бурно, Mg — медленно</td></tr>
<tr><td>Температура</td><td>нагревание ускоряет (правило Вант-Гоффа)</td></tr>
<tr><td>Концентрация</td><td>больше концентрация — выше скорость (закон действующих масс)</td></tr>
<tr><td>Давление (газы)</td><td>повышение давления = повышение концентрации газов</td></tr>
<tr><td>Площадь поверхности (гетерогенные)</td><td>порошок реагирует быстрее, чем гранула</td></tr>
<tr><td>Катализатор / ингибитор</td><td>ускоряет / замедляет</td></tr>
</table>
<div class="rule"><b>Правило Вант-Гоффа:</b> $$v_2 = v_1 \cdot \gamma^{\frac{t_2 - t_1}{10}}$$ где γ — температурный коэффициент (обычно 2–4).<br><b>Закон действующих масс</b> для элементарной реакции aA + bB → …: $v = k \cdot c_A^{\,a} \cdot c_B^{\,b}$. Концентрации твёрдых веществ в выражение не входят.</div>
<div class="example"><p><b>Пример.</b> Реакция 2NO + O<sub>2</sub> → 2NO<sub>2</sub> (элементарная). Давление увеличили в 2 раза — концентрации обоих газов выросли в 2 раза. Скорость: $v = k\,c_{NO}^2\,c_{O_2}$ вырастет в $2^2 \cdot 2 = 8$ раз.</p></div>
<div class="quick" data-a="8|в 8 раз">Температуру повысили на 30 °C, γ = 2. Во сколько раз возросла скорость?</div>`
        },
        {
          h: 'Химическое равновесие и принцип Ле Шателье',
          html: String.raw`<p>В обратимой реакции наступает <b>равновесие</b>: скорости прямой и обратной реакций равны, концентрации перестают меняться (но реакции продолжаются!).</p>
<div class="rule"><b>Принцип Ле Шателье:</b> если на систему в равновесии оказать воздействие, равновесие сместится в сторону процесса, который это воздействие ослабляет.</div>
<table class="tbl">
<tr><th>Воздействие</th><th>Куда смещается равновесие</th></tr>
<tr><td>Нагревание</td><td>в сторону эндотермической реакции (−Q)</td></tr>
<tr><td>Охлаждение</td><td>в сторону экзотермической реакции (+Q)</td></tr>
<tr><td>Повышение давления</td><td>в сторону меньшего числа моль газов</td></tr>
<tr><td>Понижение давления</td><td>в сторону большего числа моль газов</td></tr>
<tr><td>Добавление реагента / удаление продукта</td><td>вправо</td></tr>
<tr><td>Катализатор, добавление твёрдого вещества</td><td>не смещается</td></tr>
</table>
<div class="example"><p><b>Пример.</b> N<sub>2</sub>(г) + 3H<sub>2</sub>(г) ⇄ 2NH<sub>3</sub>(г) + Q. Слева 4 моль газов, справа 2. Выход аммиака растёт при повышении давления, охлаждении, отводе NH<sub>3</sub>. Катализатор (железо) лишь ускоряет достижение равновесия.</p></div>
<div class="trap"><b>Ловушки:</b> 1) давление не влияет, если число моль газов слева и справа одинаково (H<sub>2</sub> + I<sub>2</sub> ⇄ 2HI); 2) твёрдые вещества при подсчёте моль газов не учитываются; 3) «увеличение скорости прямой реакции» и «смещение вправо» — не одно и то же: катализатор ускоряет обе реакции.</div>`
        },
        {
          h: 'Расчёт равновесных концентраций (ЕГЭ 23)',
          html: String.raw`<p>Задача решается таблицей из трёх строк: <b>исходно — прореагировало — равновесие</b>. Главное: изменения концентраций пропорциональны коэффициентам уравнения.</p>
<div class="example"><p><b>Пример.</b> 2SO<sub>2</sub> + O<sub>2</sub> ⇄ 2SO<sub>3</sub>. Исходно c(SO<sub>2</sub>) = 0,6 моль/л, c(O<sub>2</sub>) = 0,4 моль/л, SO<sub>3</sub> не было. В равновесии c(SO<sub>3</sub>) = 0,4 моль/л.</p>
<table class="tbl">
<tr><th></th><th>SO<sub>2</sub></th><th>O<sub>2</sub></th><th>SO<sub>3</sub></th></tr>
<tr><td>исходно</td><td>0,6</td><td>0,4</td><td>0</td></tr>
<tr><td>изменение</td><td>−0,4</td><td>−0,2</td><td>+0,4</td></tr>
<tr><td>равновесие</td><td>0,2</td><td>0,2</td><td>0,4</td></tr>
</table>
<p>SO<sub>3</sub> образовалось 0,4 → SO<sub>2</sub> израсходовано столько же (коэффициенты 2 и 2), O<sub>2</sub> — вдвое меньше (0,2).</p></div>
<div class="tip">Если в условии дана равновесная концентрация реагента, сначала найдите, сколько его прореагировало (исходная − равновесная), а потом по коэффициентам — всё остальное.</div>`
        }
